import math, random, time, itertools, collections, functools, heapq

# Try importing solvers
try:
    import z3
    print("z3 available")
except Exception as e:
    print("z3 not available:", e)

try:
    import pysat
    print("pysat available")
except Exception as e:
    print("pysat not available:", e)

try:
    import pycosat
    print("pycosat available")
except Exception as e:
    print("pycosat not available:", e)

from pysat.solvers import Solver

n = 36
length = 2 * n

# Variable mapping: (v, i) -> var_id where i is starting position for value v
var_map = {}
var_id = 1
valid_positions = {}

for v in range(1, n+1):
    valid_positions[v] = []
    for i in range(length - v - 1):
        valid_positions[v].append(i)
        var_map[(v, i)] = var_id
        var_id += 1

print(f"Total variables: {var_id - 1}")

clauses = []

# For each value v, exactly one starting position
for v in range(1, n+1):
    vars_for_v = [var_map[(v, i)] for i in valid_positions[v]]
    clauses.append(vars_for_v)  # at least one
    for j in range(len(vars_for_v)):
        for k in range(j+1, len(vars_for_v)):
            clauses.append([-vars_for_v[j], -vars_for_v[k]])  # at most one

# For each position p, at most one value
position_vars = {p: [] for p in range(length)}
for v in range(1, n+1):
    for i in valid_positions[v]:
        position_vars[i].append(var_map[(v, i)])
        position_vars[i + v + 1].append(var_map[(v, i)])

for p in range(length):
    vars_at_p = position_vars[p]
    for j in range(len(vars_at_p)):
        for k in range(j+1, len(vars_at_p)):
            clauses.append([-vars_at_p[j], -vars_at_p[k]])

print(f"Total clauses: {len(clauses)}")

# Solve
solver = Solver(name='g3')
for clause in clauses:
    solver.add_clause(clause)

print("Solving...")
result = solver.solve()
print(f"Result: {result}")

if result:
    model = solver.get_model()
    seq = [0] * length
    for v in range(1, n+1):
        for i in valid_positions[v]:
            var = var_map[(v, i)]
            if var in model:
                seq[i] = v
                seq[i + v + 1] = v
                break

    # Verify
    ok = True
    for v in range(1, n+1):
        positions = [i for i in range(length) if seq[i] == v]
        if len(positions) != 2 or positions[1] - positions[0] != v + 1:
            print(f"Verification failed for {v}: {positions}")
            ok = False
    if ok:
        print("Verification passed!")
        print(seq)
else:
    print("UNSATISFIABLE")

solver.delete()
